    st = (t0, t1, t2, t3, t4, t5, t6, t7)
    off = tl.zeros([BLOCK], dtype=tl.int32)
    for k in tl.static_range(NDIM):
        c = rem % dims[k]
        rem = rem // dims[k]
        off += c * st[k]
